mapper.select:
select count(1)
from user_privacy_profiles


        and id = #{id}


        and user_id = #{userId}


        and profile_visibility = #{profileVisibility}


        and health_data_visible = #{healthDataVisible}


        and contact_info_visible = #{contactInfoVisible}


        and search_indexed = #{searchIndexed}


        and two_factor_auth = #{twoFactorAuth}


        and last_password_change = #{lastPasswordChange}


        and data_encryption_level = #{dataEncryptionLevel}


        and auto_logout_minutes = #{autoLogoutMinutes}


        and share_approval_required = #{shareApprovalRequired}


        and default_share_expiry_days = #{defaultShareExpiryDays}


        and last_access = #{lastAccess}


        and last_access_ip = #{lastAccessIp}


        and failed_login_attempts = #{failedLoginAttempts}


        and created_at = #{createdAt}


        and updated_at = #{updatedAt}
